<template><dialog ref="dialog" aria-labelledby="publish-title" aria-describedby="publish-description" :aria-busy="busy" @cancel="preventBusyClose" @close="emitClose"><form method="dialog" @submit.prevent><h2 id="publish-title">发布设置</h2><p id="publish-description">可以立即发布，或按北京时间安排未来发布。</p><label for="schedule-at">计划发布时间</label><input id="schedule-at" v-model="at" type="datetime-local" :disabled="disabled"><p v-if="error" role="alert">{{ error }}</p><div class="actions"><button type="button" :disabled="disabled" @click="$emit('publish')">{{busy?'处理中…':'立即发布'}}</button><button type="button" :disabled="disabled" @click="schedule">计划发布</button><button type="button" :disabled="busy" @click="close">取消</button></div></form></dialog></template>
<script setup lang="ts">import{nextTick,onMounted,ref}from'vue';import{shanghaiIso}from'../lib/schedule';const props=withDefaults(defineProps<{disabled?:boolean;busy?:boolean}>(),{disabled:false,busy:false}),emit=defineEmits<{(e:'publish'):void;(e:'schedule',iso:string):void;(e:'close'):void}>(),dialog=ref<HTMLDialogElement>(),at=ref(''),error=ref('');onMounted(async()=>{if(typeof dialog.value?.showModal==='function')dialog.value.showModal();else dialog.value?.setAttribute('open','');await nextTick();dialog.value?.querySelector<HTMLButtonElement>('button')?.focus()});function schedule(){if(props.disabled)return;const iso=shanghaiIso(at.value);if(!iso){error.value='请选择未来的北京时间';return}emit('schedule',iso)}function close(){if(props.busy)return;dialog.value?.close()}function emitClose(){if(!props.busy)emit('close')}function preventBusyClose(e:Event){if(props.busy)e.preventDefault()}</script>
<style scoped>dialog{width:min(92vw,520px);border:1px solid #c9bdb1;border-radius:10px;padding:24px}dialog::backdrop{background:#20181099}label,input{display:block;width:100%;margin:10px 0}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}</style>
